-- schemas: public
-- An e-commerce schema in the style of the classic sample databases.
CREATE TYPE order_status AS ENUM ('cart', 'placed', 'paid', 'shipped', 'delivered', 'cancelled', 'refunded');
CREATE TYPE payment_method AS ENUM ('card', 'paypal', 'bank_transfer', 'gift_card');
CREATE DOMAIN email_address AS text CHECK (VALUE ~* '^[^@\s]+@[^@\s]+$');
CREATE DOMAIN money_amount AS numeric(12,2) CHECK (VALUE >= 0);

CREATE TABLE customers (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email       email_address NOT NULL UNIQUE,
    full_name   text NOT NULL,
    phone       text,
    marketing   boolean NOT NULL DEFAULT false,
    preferences jsonb NOT NULL DEFAULT '{}',
    created_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);
CREATE UNIQUE INDEX customers_live_email ON customers (lower(email::text)) WHERE deleted_at IS NULL;

CREATE TABLE addresses (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id uuid NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    kind        text NOT NULL DEFAULT 'shipping' CHECK (kind IN ('shipping', 'billing')),
    line1       text NOT NULL,
    line2       text,
    city        text NOT NULL,
    region      text,
    postal_code text,
    country     char(2) NOT NULL,
    location    point
);

CREATE TABLE categories (
    id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id integer REFERENCES categories (id),
    name      text NOT NULL,
    slug      text NOT NULL UNIQUE
);

CREATE TABLE products (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sku         varchar(32) NOT NULL UNIQUE,
    name        text NOT NULL,
    description text,
    price       money_amount NOT NULL,
    weight_g    integer CHECK (weight_g > 0),
    tags        text[] NOT NULL DEFAULT '{}',
    attributes  jsonb,
    search      tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(description, ''))) STORED,
    active      boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX products_search ON products USING gin (search);
CREATE INDEX products_tags ON products USING gin (tags);

CREATE TABLE product_categories (
    product_id  bigint  NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    category_id integer NOT NULL REFERENCES categories (id),
    PRIMARY KEY (product_id, category_id)
);

CREATE TABLE orders (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id uuid NOT NULL REFERENCES customers (id),
    status      order_status NOT NULL DEFAULT 'cart',
    ship_to     bigint REFERENCES addresses (id),
    bill_to     bigint REFERENCES addresses (id),
    placed_at   timestamptz,
    note        text,
    CHECK (status = 'cart' OR placed_at IS NOT NULL)
);

CREATE TABLE order_items (
    order_id   bigint   NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    line_no    smallint NOT NULL,
    product_id bigint   NOT NULL REFERENCES products (id),
    quantity   integer  NOT NULL CHECK (quantity > 0),
    unit_price money_amount NOT NULL,
    line_total numeric(14,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
    PRIMARY KEY (order_id, line_no)
);

CREATE TABLE payments (
    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id  bigint NOT NULL REFERENCES orders (id),
    method    payment_method NOT NULL,
    amount    money_amount NOT NULL,
    reference text,
    paid_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE reviews (
    customer_id uuid   NOT NULL REFERENCES customers (id),
    product_id  bigint NOT NULL REFERENCES products (id),
    rating      smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
    body        text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (customer_id, product_id)
);

CREATE TABLE inventory (
    product_id bigint NOT NULL REFERENCES products (id),
    warehouse  text   NOT NULL,
    on_hand    integer NOT NULL DEFAULT 0,
    reserved   integer NOT NULL DEFAULT 0,
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (product_id, warehouse)
);

CREATE TABLE audit_log (
    id         bigserial,
    at         timestamptz NOT NULL DEFAULT now(),
    actor      text,
    action     text NOT NULL,
    subject    text,
    detail     jsonb,
    client_ip  inet,
    PRIMARY KEY (id, at)
) PARTITION BY RANGE (at);
CREATE TABLE audit_log_2025 PARTITION OF audit_log FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE TABLE audit_log_2026 PARTITION OF audit_log FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE audit_log_other PARTITION OF audit_log DEFAULT;

CREATE VIEW order_summary AS
    SELECT o.id AS order_id, o.customer_id, o.status, count(i.line_no) AS lines, coalesce(sum(i.line_total), 0) AS total
    FROM orders o LEFT JOIN order_items i ON i.order_id = o.id
    GROUP BY o.id;
CREATE MATERIALIZED VIEW daily_sales AS
    SELECT date_trunc('day', placed_at)::date AS day, count(*) AS orders
    FROM orders WHERE placed_at IS NOT NULL GROUP BY 1;

CREATE FUNCTION order_total(p_order bigint) RETURNS numeric LANGUAGE sql STABLE
    AS $$ SELECT coalesce(sum(line_total), 0) FROM order_items WHERE order_id = p_order $$;
